// Package ids creates and parses the identifiers of every row the server owns.
//
// Every ID is a UUIDv7 (RFC 9562 section 5.7) generated by the application, not by the database
// (docs/spec/03-data-model.md, "Principles" item 1): the first 48 bits are Unix milliseconds, so
// IDs sort by creation time and keep B-tree indexes compact. IDs of one process are strictly
// increasing, also within one millisecond and when the system clock steps back (RFC 9562 section
// 6.2, method "Monotonic Random"), so an ID created later never sorts before an earlier one.
//
// The API writes IDs in lower case and accepts upper case on input
// (docs/spec/06-api.md, "Basic rules"); [ID.String] and [Parse] implement both rules.
//
// Example:
//
//	id := ids.New()
//	s := id.String()        // "0192a3b4-c5d6-7e8f-9a0b-1c2d3e4f5a6b", for example
//	back, err := ids.Parse(s)
//	// back == id, err == nil
package ids

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"sync"
	"time"

	"github.com/OWNER/bothy/services/server/internal/kernel/clock"
)

// ID is a UUIDv7 in its 16-byte binary form, in network byte order.
//
// The zero value is the nil UUID, which is never a valid row ID; [ID.IsZero] reports it. Comparing
// two IDs with == or bytes.Compare is meaningful: the byte order is the creation order.
type ID [16]byte

// ErrInvalid is wrapped by every error of [Parse] and [ID.UnmarshalText].
//
// Callers test for it with errors.Is to map bad input to a validation error. The wrapping errors
// never contain the input, because the input may be anything a client sent.
var ErrInvalid = errors.New("ids: invalid UUIDv7")

const (
	// textLen is the length of the canonical 8-4-4-4-12 form.
	textLen = 36

	// maxMillis is the largest timestamp the 48-bit field holds (year 10889).
	maxMillis = 1<<48 - 1

	// randAMax and randBMax bound the two random fields that together form the 74-bit counter of
	// RFC 9562 section 6.2 method 2: rand_a has 12 bits, rand_b 62 bits.
	randAMax = 1<<12 - 1
	randBMax = 1<<62 - 1

	// version7 is the version nibble in the high bits of byte 6, positioned for the low 16 bits
	// (bytes 6 and 7) of the first big-endian word that encode writes.
	version7 = 0x7000

	// variantRFC is the variant "10" in the two high bits of byte 8.
	variantRFC = 1 << 63
)

// Generator creates strictly increasing UUIDv7 values.
//
// A Generator is safe for concurrent use; a mutex guards its state. Most code calls the package
// function [New]; a Generator of its own is for tests that need a fixed clock or random source.
type Generator struct {
	clock  clock.Clock
	random io.Reader

	mu     sync.Mutex
	lastMs uint64 // timestamp of the last ID, never decreases
	randA  uint64 // high 12 bits of the counter
	randB  uint64 // low 62 bits of the counter
}

// NewGenerator returns a generator that reads the time from c and random bits from random.
//
// Both arguments are required; a nil argument is a programming error and panics with a message
// that starts with "ids: ". The random reader should be cryptographically secure (crypto/rand),
// because IDs appear in URLs and must not be guessable from their neighbors.
//
// Example (in a test):
//
//	g := ids.NewGenerator(clock.NewFake(time.Date(2026, 10, 11, 9, 0, 0, 0, time.UTC)), rand.Reader)
//	first, second := g.New(), g.New() // same millisecond, second > first
func NewGenerator(c clock.Clock, random io.Reader) *Generator {
	if c == nil {
		panic("ids: NewGenerator called with a nil clock")
	}
	if random == nil {
		panic("ids: NewGenerator called with a nil random reader")
	}
	return &Generator{clock: c, random: random}
}

// New returns the next ID of this generator; it is greater than every ID g returned before.
//
// In a new millisecond the 74 counter bits are drawn fresh. In the same millisecond, or when the
// clock went back, the counter grows by a random step in [1, 2^32), which keeps the order strict
// and the next value hard to guess. If the counter overflows, the timestamp moves one millisecond
// ahead of the clock and the counter is drawn fresh; later calls use that timestamp until the clock
// passes it.
//
// New panics with a message starting with "ids: " if the random reader fails or the timestamp
// is before 1970 or beyond the 48-bit range: both are faults of the host or the program that no
// caller can handle, and an ID that breaks the order would corrupt data silently. A panic leaves
// the generator unchanged, so a caller that recovers gets the ID the failed call would have
// returned.
func (g *Generator) New() ID {
	g.mu.Lock()
	defer g.mu.Unlock()

	// Work on copies and commit them only after every random draw succeeded.
	ms := millis(g.clock.Now())
	if ms > g.lastMs {
		a, b := g.seed()
		return g.commit(ms, a, b)
	}

	ms, a, b := g.lastMs, g.randA, g.randB+g.step()
	if b > randBMax {
		b &= randBMax
		a++
	}
	if a > randAMax {
		if ms == maxMillis {
			panic("ids: counter overflow at the last representable millisecond")
		}
		ms++
		a, b = g.seed()
	}
	return g.commit(ms, a, b)
}

// millis converts t to Unix milliseconds and proves the 48-bit range before the conversion.
func millis(t time.Time) uint64 {
	ms := t.UnixMilli()
	if ms < 0 || ms > maxMillis {
		panic(fmt.Sprintf("ids: clock time %s is outside the UUIDv7 timestamp range",
			t.UTC().Format(time.RFC3339Nano)))
	}
	return uint64(ms)
}

// seed draws 74 fresh counter bits and returns them as rand_a and rand_b.
func (g *Generator) seed() (a, b uint64) {
	var buf [10]byte
	g.read(buf[:])
	return uint64(binary.BigEndian.Uint16(buf[0:2])) & randAMax,
		binary.BigEndian.Uint64(buf[2:10]) & randBMax
}

// step draws the increment for an ID in the same millisecond, in [1, 2^32).
func (g *Generator) step() uint64 {
	var b [4]byte
	g.read(b[:])
	if r := binary.BigEndian.Uint32(b[:]); r != 0 {
		return uint64(r)
	}
	return 1
}

// read fills b from the random reader and panics if it cannot.
func (g *Generator) read(b []byte) {
	if _, err := io.ReadFull(g.random, b); err != nil {
		panic(fmt.Sprintf("ids: read random bits: %v", err))
	}
}

// commit stores the new state and returns it as an ID laid out per RFC 9562 section 5.7:
// unix_ts_ms (48) | ver (4) | rand_a (12) | var (2) | rand_b (62).
func (g *Generator) commit(ms, a, b uint64) ID {
	g.lastMs, g.randA, g.randB = ms, a, b
	var id ID
	binary.BigEndian.PutUint64(id[0:8], ms<<16|version7|a)
	binary.BigEndian.PutUint64(id[8:16], variantRFC|b)
	return id
}

// defaultGenerator backs the package function New for the whole process, so that all IDs of the
// process share one monotonic sequence.
var defaultGenerator = NewGenerator(clock.System(), rand.Reader)

// New returns a new ID from the process-wide generator (system clock, crypto/rand).
//
// IDs from New are strictly increasing within the process, across goroutines. New panics only if
// the operating system's random source fails or the system clock is outside the range 1970 to
// 10889; see [Generator.New].
func New() ID { return defaultGenerator.New() }

// Parse reads an ID in the canonical form 8-4-4-4-12 with hexadecimal digits in any case.
//
// Parse accepts only version 7 with the RFC variant, so the nil and the max UUID, UUIDs of other
// versions, braces, the "urn:uuid:" prefix and any length other than 36 are rejected. The error
// wraps [ErrInvalid] and describes the defect without repeating the input; a position in it is the
// 0-based byte index of the offending character.
//
// Example:
//
//	id, err := ids.Parse("017F22E2-79B0-7CC3-98C4-DC0C0C07398F")
//	// err == nil, id.String() == "017f22e2-79b0-7cc3-98c4-dc0c0c07398f"
func Parse(s string) (ID, error) {
	if len(s) != textLen {
		return ID{}, fmt.Errorf("%w: length %d, want %d", ErrInvalid, len(s), textLen)
	}
	var id ID
	n := 0
	for i := 0; i < textLen; {
		if i == 8 || i == 13 || i == 18 || i == 23 {
			if s[i] != '-' {
				return ID{}, fmt.Errorf("%w: want '-' at position %d", ErrInvalid, i)
			}
			i++
			continue
		}
		hi, okHi := hexValue(s[i])
		if !okHi {
			return ID{}, fmt.Errorf("%w: non-hexadecimal character at position %d", ErrInvalid, i)
		}
		lo, okLo := hexValue(s[i+1])
		if !okLo {
			return ID{}, fmt.Errorf("%w: non-hexadecimal character at position %d", ErrInvalid, i+1)
		}
		id[n] = hi<<4 | lo
		n++
		i += 2
	}
	if id[6]>>4 != 7 {
		return ID{}, fmt.Errorf("%w: version %d, want 7", ErrInvalid, id[6]>>4)
	}
	if id[8]>>6 != 0b10 {
		return ID{}, fmt.Errorf("%w: variant bits %02b, want 10", ErrInvalid, id[8]>>6)
	}
	return id, nil
}

// hexValue returns the value of one hexadecimal digit in either case.
func hexValue(c byte) (byte, bool) {
	switch {
	case '0' <= c && c <= '9':
		return c - '0', true
	case 'a' <= c && c <= 'f':
		return c - 'a' + 10, true
	case 'A' <= c && c <= 'F':
		return c - 'A' + 10, true
	default:
		return 0, false
	}
}

// MustParse is [Parse] for constants and tests; it panics if s is not a valid ID.
//
// Never use it on input from outside the program: a client must get a validation error, not a
// crashed request.
func MustParse(s string) ID {
	id, err := Parse(s)
	if err != nil {
		panic(err)
	}
	return id
}

// String returns the canonical lower-case form 8-4-4-4-12, as the API writes IDs.
func (id ID) String() string {
	var b [textLen]byte
	id.appendText(b[:0])
	return string(b[:])
}

// appendText appends the canonical form to dst.
func (id ID) appendText(dst []byte) []byte {
	dst = hex.AppendEncode(dst, id[0:4])
	dst = append(dst, '-')
	dst = hex.AppendEncode(dst, id[4:6])
	dst = append(dst, '-')
	dst = hex.AppendEncode(dst, id[6:8])
	dst = append(dst, '-')
	dst = hex.AppendEncode(dst, id[8:10])
	dst = append(dst, '-')
	return hex.AppendEncode(dst, id[10:16])
}

// IsZero reports whether id is the nil UUID, the zero value of [ID] that no generator returns.
func (id ID) IsZero() bool { return id == ID{} }

// StringOrEmpty returns the text form of id, or the empty string for the zero ID (an absent
// optional member).
func (id ID) StringOrEmpty() string {
	if id.IsZero() {
		return ""
	}
	return id.String()
}

// Time returns the creation instant stored in the first 48 bits, in UTC with millisecond
// precision. For the zero ID it returns the Unix epoch.
func (id ID) Time() time.Time {
	ms := int64(id[0])<<40 | int64(id[1])<<32 | int64(id[2])<<24 |
		int64(id[3])<<16 | int64(id[4])<<8 | int64(id[5])
	return time.UnixMilli(ms).UTC()
}

// MarshalText implements encoding.TextMarshaler with the lower-case form of [ID.String], so
// JSON and other text encodings write IDs the way the API requires. It never fails.
func (id ID) MarshalText() ([]byte, error) {
	return id.appendText(make([]byte, 0, textLen)), nil
}

// UnmarshalText implements encoding.TextUnmarshaler with the rules of [Parse]. On error the
// receiver is left unchanged and the error wraps [ErrInvalid].
func (id *ID) UnmarshalText(text []byte) error {
	parsed, err := Parse(string(text))
	if err != nil {
		return err
	}
	*id = parsed
	return nil
}
